namespace humhub\helpers;

use Yii;

/**
 * The data of the emoji picker
 *
 * Emojis are stored as Unicode and rendered by the Noto emoji font ([[\humhub\assets\EmojiFontAsset]]).
 *
 * @see docs/develop/internals-emoji.md
 * @since 1.20
 */
class EmojiHelper
{
    /**
     * Directory of the picker data per language, generated by emoji.build.mjs
     */
    public const DATA_PATH = '@humhub/resources/emoji/data';

    /**
     * @return string the language of the picker data closest to the language, e.g. `pt` for `pt-BR`, else `en`
     */
    public static function getDataLocale(?string $language = null): string
    {
        $language = strtolower(str_replace('_', '-', $language ?? Yii::$app->language));
        $aliases = ['zh-tw' => 'zh-hant', 'zh-hk' => 'zh-hant', 'zh-cn' => 'zh', 'nb-no' => 'nb', 'no' => 'nb'];
        $candidates = [$aliases[$language] ?? $language, explode('-', $language)[0]];

        foreach ($candidates as $locale) {
            if (preg_match('/^[a-z-]+$/', $locale) && is_file(Yii::getAlias(self::DATA_PATH) . '/' . $locale . '.json')) {
                return $locale;
            }
        }

        return 'en';
    }

    /**
     * @return string the URL of the picker data of the language
     */
    public static function getDataUrl(?string $language = null): string
    {
        return Yii::$app->assetManager->getPublishedUrl('@humhub/resources')
            . '/emoji/data/' . static::getDataLocale($language) . '.json';
    }
}
